"""Edge-case tests for interactive-slots — generated by bug-hunter agent.

Targets the per-(panel, slot) interactive runtime contract introduced by
GH #52 (secondary y-axis) and the GH #16 shared-legend band, as emitted in
the interactive scene JSON:

- ``coord.y_domains`` per-slot y-domain list (slot 0 mirrors ``y_domain``)
- ``MarkBatch.y_slot`` slot ids on mark batches (omitted when 0)
- ``interaction.tick_levels[*].y_slot_levels`` per-right-axis tick levels
- ``interaction.param_bindings[*].y_slot`` for slotted domainParams
- per-layer tooltips on slotted batches
- shared-legend band geometry (panels reclaim the per-panel legend gutters)

All assertions go through ``ferrum._interactive._render_scene`` — the same
``(scene_json, packed)`` producer that ``.interactive()`` / ``to_html()`` use —
so they pin the wire contract the WASM runtime deserializes.
"""

from __future__ import annotations

import json
import math

import polars as pl
import pytest

import ferrum as fm
from ferrum._interactive import _render_scene


# ── helpers ─────────────────────────────────────────────────────────────────


def _dual_df() -> pl.DataFrame:
    return pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0, 4.0],
            "y1": [10.0, 20.0, 30.0, 40.0],
            "y2": [0.1, 0.2, 0.3, 0.4],
        }
    )


def _dual_layer(df: pl.DataFrame | None = None) -> "fm.LayerChart":
    """Two-layer independent-y chart: y1 on slot 0, y2 on slot 1."""
    df = df if df is not None else _dual_df()
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_line().encode(x="x", y="y2")
    return fm.LayerChart(a, b, resolve={"y": "independent"})


def _scene(chart) -> dict:
    scene_json, _packed = _render_scene(chart)
    return json.loads(scene_json)


def _reject_constant(name: str) -> None:
    raise ValueError(f"bare JSON constant {name!r} in scene JSON")


# ============================================================================
# Per-slot y-domain contract (coord.y_domains, e3bae7f6)
# ============================================================================


def test_dual_axis_scene_emits_per_slot_y_domains():
    """An independent-y LayerChart panel must carry one y_domains entry per slot.

    Exercises ``scene_build.rs``'s ``scales.y_slots.has_independent()`` branch
    that populates ``CoordKind::Cartesian::y_domains``.
    """
    scene = _scene(_dual_layer())
    coord = scene["panels"][0]["coord"]
    assert coord["kind"] == "cartesian"
    y_domains = coord.get("y_domains")
    assert y_domains is not None, "dual-axis panel must emit y_domains"
    assert len(y_domains) == 2, f"expected 2 slots, got {y_domains}"
    lo1, hi1 = y_domains[1]
    assert lo1 <= 0.1 and hi1 >= 0.4, f"slot-1 domain must cover y2 extent, got {y_domains[1]}"


def test_dual_axis_slot0_domain_mirrors_legacy_y_domain():
    """Slot 0 of y_domains must equal the legacy y_domain field.

    ``param_runtime::axis_domain_slot`` prefers ``y_domains[0]`` over
    ``y_domain`` when slots are present; divergence between the two would make
    a brush on the primary layer invert through a different domain than the
    axis labels display.
    """
    coord = _scene(_dual_layer())["panels"][0]["coord"]
    assert coord["y_domains"][0] == coord["y_domain"], (
        f"slot 0 {coord['y_domains'][0]} must mirror legacy y_domain {coord['y_domain']}"
    )


def test_single_y_chart_omits_y_domains_key():
    """Byte-stability: a plain single-y chart must NOT emit y_domains.

    Pins the ``skip_serializing_if = "Vec::is_empty"`` contract on
    ``CoordKind::Cartesian::y_domains`` — the WASM loader treats a missing key
    as slot count 1.
    """
    df = _dual_df()
    chart = fm.Chart(df).mark_line().encode(x="x", y="y1")
    coord = _scene(chart)["panels"][0]["coord"]
    assert "y_domains" not in coord, f"single-y coord must omit y_domains: {coord}"


def test_three_layer_independent_y_emits_three_slots():
    """Three independent-y layers → 3 slot domains, slots [0,1,2], 2 right axes."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y1": [10.0, 20.0, 30.0],
            "y2": [0.1, 0.2, 0.3],
            "y3": [100.0, 200.0, 300.0],
        }
    )
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_line().encode(x="x", y="y2")
    c = fm.Chart(df).mark_line().encode(x="x", y="y3")
    scene = _scene(fm.LayerChart(a, b, c, resolve={"y": "independent"}))
    panel = scene["panels"][0]
    assert len(panel["coord"]["y_domains"]) == 3
    slots = [mb.get("y_slot", 0) for mb in panel["marks"]]
    assert slots == [0, 1, 2], f"expected slots [0,1,2], got {slots}"
    y_slot_levels = scene["interaction"]["tick_levels"][0].get("y_slot_levels", [])
    assert len(y_slot_levels) == 2, "3 slots → 2 secondary right axes"


# ============================================================================
# Slot ids on mark batches (MarkBatch.y_slot, 9fd2ffc5)
# ============================================================================


def test_dual_axis_mark_batches_carry_slot_ids():
    """Batch 0 must default to slot 0 (key omitted); batch 1 must carry y_slot=1.

    Pins both halves of the serde contract: ``is_zero_usize`` skip on the
    primary batch (byte-stability) and the explicit slot id on the
    independent-y batch (what the WASM render loop binds its affine by).
    """
    panel = _scene(_dual_layer())["panels"][0]
    assert len(panel["marks"]) == 2
    assert "y_slot" not in panel["marks"][0], "slot 0 must be omitted from JSON"
    assert panel["marks"][1].get("y_slot") == 1, (
        f"secondary batch must carry y_slot=1, got {panel['marks'][1].get('y_slot')}"
    )


def test_secondary_y_sugar_emits_same_slot_contract():
    """fm.SecondaryY desugars to the identical slot contract as LayerChart."""
    df = _dual_df()
    base = fm.Chart(df).mark_line().encode(x="x", y="y1")
    scene = _scene(base + fm.SecondaryY("y2"))
    panel = scene["panels"][0]
    assert len(panel["coord"]["y_domains"]) == 2
    slots = [mb.get("y_slot", 0) for mb in panel["marks"]]
    assert slots == [0, 1], f"SecondaryY must produce slots [0, 1], got {slots}"
    assert scene["interaction"]["tick_levels"][0].get("y_slot_levels"), (
        "SecondaryY must emit y_slot_levels for its right axis"
    )


# ============================================================================
# Per-slot tick levels (interaction.tick_levels.y_slot_levels)
# ============================================================================


def test_dual_axis_tick_levels_carry_y_slot_levels_in_slot_domain():
    """y_slot_levels[0] ticks must be generated from slot 1's OWN scale.

    If the secondary axis's tick levels were generated from the primary scale,
    zoom relabeling in ``text_json::build_zoomed_text_json`` could never
    recognize right-axis labels. Primary ticks live in [10, 40]; slot-1 ticks
    must live in the y2 domain [0.1, 0.4] — disjoint ranges, so this is a
    discriminating check.
    """
    scene = _scene(_dual_layer())
    ptl = scene["interaction"]["tick_levels"][0]
    assert ptl.get("y_slot_levels"), "dual-axis chart must emit y_slot_levels"
    slot1_values = [t["value"] for lvl in ptl["y_slot_levels"][0] for t in lvl["ticks"]]
    assert slot1_values, "slot-1 tick levels must contain ticks"
    assert all(v <= 1.0 for v in slot1_values), (
        f"slot-1 ticks must come from the y2 scale (values ≤ 1.0), got {slot1_values}"
    )
    primary_values = [t["value"] for lvl in ptl["y_levels"] for t in lvl["ticks"]]
    assert all(v >= 10.0 or v == 0.0 for v in primary_values), (
        f"primary ticks must come from the y1 scale, got {primary_values}"
    )


def test_single_y_chart_omits_y_slot_levels_key():
    """Byte-stability: a single-y chart's tick_levels entry must omit y_slot_levels."""
    df = _dual_df()
    chart = fm.Chart(df).mark_line().encode(x="x", y="y1")
    ptl = _scene(chart)["interaction"]["tick_levels"][0]
    assert "y_slot_levels" not in ptl, f"single-y tick levels must omit y_slot_levels: {ptl.keys()}"


# ============================================================================
# domainParam targeting a slotted scale (ParamBinding.y_slot)
# ============================================================================


def test_domain_param_on_secondary_layer_binding_carries_y_slot():
    """A domainParam on the independent-y layer's y must emit y_slot=1."""
    df = _dual_df()
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_line().encode(
        x="x", y=fm.Y("y2", scale={"domain": fm.param("d2", value=[0.0, 1.0])})
    )
    scene = _scene(fm.LayerChart(a, b, resolve={"y": "independent"}))
    bindings = scene["interaction"].get("param_bindings") or []
    domain_bindings = [pb for pb in bindings if pb["role"] == "domain"]
    assert domain_bindings, "domainParam must emit a Domain binding"
    pb = domain_bindings[0]
    assert pb["channel"] == "y"
    assert pb.get("y_slot") == 1, f"binding must target slot 1, got {pb}"


def test_domain_param_on_primary_layer_of_dual_axis_resolves_static_domain():
    """Control: a domainParam on the PRIMARY layer statically resolves slot 0.

    This is the passing sibling of the failing slot-1 test below — it proves
    the static resolver knows how to substitute a param initial value into a
    slot domain when the slot is the primary one.
    """
    df = _dual_df()
    a = fm.Chart(df).mark_line().encode(
        x="x", y=fm.Y("y1", scale={"domain": fm.param("d1", value=[0.0, 100.0])})
    )
    b = fm.Chart(df).mark_line().encode(x="x", y="y2")
    coord = _scene(fm.LayerChart(a, b, resolve={"y": "independent"}))["panels"][0]["coord"]
    assert coord["y_domains"][0] == [0.0, 100.0], (
        f"primary-layer domainParam initial value must resolve into slot 0, got {coord['y_domains']}"
    )


def test_explicit_static_domain_on_secondary_layer_is_honored():
    """Control: a literal scale domain on the secondary layer resolves slot 1."""
    df = _dual_df()
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_line().encode(x="x", y=fm.Y("y2", scale={"domain": [0.0, 1.0]}))
    coord = _scene(fm.LayerChart(a, b, resolve={"y": "independent"}))["panels"][0]["coord"]
    assert coord["y_domains"][1] == [0.0, 1.0], (
        f"explicit slot-1 domain must be honored, got {coord['y_domains']}"
    )


def test_domain_param_on_secondary_layer_resolves_static_slot_domain():  # BUG: domainParam initial value on an independent-y layer is ignored — y_domains[1] stays at the data extent instead of the param value, while the identical param on slot 0 (and on any single-y chart) resolves correctly
    """A domainParam's initial value on the secondary layer must resolve slot 1.

    The static resolver substitutes ``domainParam`` initial values into scale
    domains before the scene exists (D6 wire contract). A single-y chart and
    the slot-0 layer both honor this (see the two control tests above), and the
    slot-1 *binding* is emitted (``y_slot: 1``) — but the slot-1 *domain* in
    ``y_domains`` silently keeps the auto-inferred data extent [0.1, 0.4]
    instead of the declared [0.0, 1.0]. The static SVG and the initial
    interactive view therefore render the secondary layer at the wrong domain
    until the first live param update.
    """
    df = _dual_df()
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_line().encode(
        x="x", y=fm.Y("y2", scale={"domain": fm.param("d2", value=[0.0, 1.0])})
    )
    coord = _scene(fm.LayerChart(a, b, resolve={"y": "independent"}))["panels"][0]["coord"]
    assert coord["y_domains"][1] == [0.0, 1.0], (
        f"slot-1 domainParam initial value [0.0, 1.0] must resolve into "
        f"y_domains[1], got {coord['y_domains'][1]}"
    )


# ============================================================================
# Per-layer tooltips on slotted batches (bf40ee49)
# ============================================================================


def test_dual_axis_per_layer_tooltips_reference_own_y_field():
    """Each slotted batch's auto-tooltips must name that layer's own y column.

    Two layers overlap in the same panel; if tooltip generation ran against the
    merged chart's first y encoding, the slot-1 batch would report ``y1``
    values for ``y2`` marks.
    """
    panel = _scene(_dual_layer())["panels"][0]
    tips0 = panel["marks"][0].get("tooltips")
    tips1 = panel["marks"][1].get("tooltips")
    assert tips0 and tips1, "both slotted batches must carry tooltips"
    fields0 = {f["name"] for f in tips0[0]["fields"]}
    fields1 = {f["name"] for f in tips1[0]["fields"]}
    assert "y1" in fields0 and "y2" not in fields0, f"slot-0 tooltip fields: {fields0}"
    assert "y2" in fields1 and "y1" not in fields1, f"slot-1 tooltip fields: {fields1}"
    # The value must be the layer's own datum, not the sibling's.
    val1 = next(f["value"] for f in tips1[0]["fields"] if f["name"] == "y2")
    assert float(val1) == pytest.approx(0.1), f"slot-1 first tooltip must be y2=0.1, got {val1}"


# ============================================================================
# Extreme / degenerate / type-boundary data through the slot pipeline
# ============================================================================


def test_infinity_in_secondary_column_produces_finite_slot_domain():
    """Inf in the slot-1 column must not leak into y_domains or the JSON.

    A bare ``Infinity`` token in the scene JSON parses in Python but is a
    syntax error in every browser's ``JSON.parse`` — the WASM loader would
    reject the whole scene. ``parse_constant`` rejection asserts no bare
    Infinity/NaN token exists anywhere in the payload.
    """
    df = pl.DataFrame(
        {"x": [1.0, 2.0, 3.0], "y1": [1.0, 2.0, 3.0], "y2": [0.1, float("inf"), 0.3]}
    )
    scene_json, _ = _render_scene(_dual_layer(df))
    scene = json.loads(scene_json, parse_constant=_reject_constant)
    y_domains = scene["panels"][0]["coord"]["y_domains"]
    lo, hi = y_domains[1]
    assert math.isfinite(lo) and math.isfinite(hi), f"slot-1 domain must be finite, got {y_domains}"


def test_all_identical_secondary_values_produce_nondegenerate_slot_domain():
    """A constant slot-1 column must not collapse the domain to a zero-span point.

    ``param_runtime::pixel_to_data`` divides by the domain span; a (5.0, 5.0)
    domain would make every slot-1 brush/rescale degenerate.
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y1": [1.0, 2.0, 3.0], "y2": [5.0, 5.0, 5.0]})
    y_domains = _scene(_dual_layer(df))["panels"][0]["coord"]["y_domains"]
    lo, hi = y_domains[1]
    assert lo < hi, f"constant column must yield a padded (non-degenerate) domain, got {y_domains[1]}"
    assert lo <= 5.0 <= hi


def test_null_values_in_secondary_column_do_not_poison_slot_domain():
    """Nulls in the slot-1 column must be skipped, not become NaN in the domain."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y1": [1.0, 2.0, 3.0], "y2": [0.1, None, 0.3]})
    scene_json, _ = _render_scene(_dual_layer(df))
    scene = json.loads(scene_json, parse_constant=_reject_constant)
    y_domains = scene["panels"][0]["coord"]["y_domains"]
    lo, hi = y_domains[1]
    assert math.isfinite(lo) and math.isfinite(hi)
    assert lo <= 0.1 and hi >= 0.3


def test_ordinal_secondary_layer_emits_null_slot_domain():
    """A string-typed slot-1 column must emit y_domains[1] = null, not crash.

    ``axis_domain_slot`` documents that a ``None`` slot entry (ordinal/band
    scale) makes pixel↔data conversion undefined and the binding skipped — the
    scene must encode that as JSON ``null``.
    """
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y1": [1.0, 2.0, 3.0], "y2": ["a", "b", "c"]})
    a = fm.Chart(df).mark_line().encode(x="x", y="y1")
    b = fm.Chart(df).mark_point().encode(x="x", y="y2")
    coord = _scene(fm.LayerChart(a, b, resolve={"y": "independent"}))["panels"][0]["coord"]
    y_domains = coord["y_domains"]
    assert len(y_domains) == 2
    assert y_domains[1] is None, f"ordinal slot must serialize as null, got {y_domains[1]}"
    assert y_domains[0] is not None, "quantitative slot 0 must keep its domain"


def test_zero_row_dual_axis_interactive_returns_valid_empty_scene():
    """A zero-row dual-axis chart must produce the empty-scene JSON, not raise.

    Exercises the ``_empty_scene_json`` bypass in ``ferrum._scene`` through the
    LayerChart ``_render_interactive`` path.
    """
    scene_json, packed = _render_scene(_dual_layer(_dual_df().head(0)))
    scene = json.loads(scene_json, parse_constant=_reject_constant)
    assert scene["panels"] == []
    assert packed == b""
    assert scene["width"] > 0 and scene["height"] > 0


# ============================================================================
# Composition corners: slots must survive composite placement
# ============================================================================


def test_dual_axis_inside_hconcat_preserves_slot_contract():
    """hconcat(dual-axis leaf, plain leaf): composite placement must not strip
    y_domains or batch y_slot from the dual leaf (composite_render.rs carries a
    debug assertion for exactly this; pin it from Python).
    """
    df = _dual_df()
    plain = fm.Chart(df).mark_point().encode(x="x", y="y1")
    scene = _scene(fm.hconcat(_dual_layer(), plain))
    dual_panels = [p for p in scene["panels"] if p["coord"].get("y_domains")]
    assert len(dual_panels) == 1, "exactly one panel must carry the slot contract"
    panel = dual_panels[0]
    assert len(panel["coord"]["y_domains"]) == 2
    slots = [mb.get("y_slot", 0) for mb in panel["marks"]]
    assert slots == [0, 1], f"slots must survive composite placement, got {slots}"
    plain_panels = [p for p in scene["panels"] if not p["coord"].get("y_domains")]
    assert plain_panels, "the plain leaf must NOT grow a y_domains list"
    assert all("y_slot" not in mb for p in plain_panels for mb in p["marks"])


# ============================================================================
# GH #16 shared-legend band in interactive export
# ============================================================================


def _legend_pair(shared: bool):
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, 2.0, 3.0], "g": ["a", "b", "a"]})
    left = fm.Chart(df).mark_point().encode(x="x", y="y", color="g")
    right = fm.Chart(df).mark_point().encode(x="x", y="y", color="g")
    if shared:
        return fm.hconcat(
            left,
            right,
            resolve=fm.Resolve(scale={"color": "shared"}, legend={"color": "shared"}),
        )
    return fm.hconcat(left, right)


def test_shared_legend_hconcat_emits_single_deduped_legend():
    """Resolve(legend={'color': 'shared'}) must emit ONE figure-level legend,
    with fewer legend nodes than the two per-panel legends of the default."""
    shared = _scene(_legend_pair(shared=True))
    independent = _scene(_legend_pair(shared=False))
    assert len(shared["legend"]) < len(independent["legend"]), (
        f"shared legend must dedup: shared={len(shared['legend'])} nodes, "
        f"independent={len(independent['legend'])} nodes"
    )
    labels = [n["content"] for n in shared["legend"] if n["type"] == "text"]
    assert labels.count("a") == 1 and labels.count("b") == 1, (
        f"each category must appear exactly once in the shared legend, got {labels}"
    )


def test_shared_legend_band_widens_panels_without_overlap():
    """Reclaiming the per-panel legend gutters must widen plot areas, and the
    widened panels must not overlap each other or the legend band's x-extent.
    A hit-region offset bug (band shifting panels but not marks, or vice versa)
    would surface as overlapping plot areas here."""
    shared = _scene(_legend_pair(shared=True))
    independent = _scene(_legend_pair(shared=False))
    sw = [p["plot_area"]["w"] for p in shared["panels"]]
    iw = [p["plot_area"]["w"] for p in independent["panels"]]
    assert all(s > i for s, i in zip(sw, iw)), (
        f"shared-legend panels must be wider (gutter reclaimed): shared={sw}, independent={iw}"
    )
    p0, p1 = (p["plot_area"] for p in shared["panels"])
    left, right = (p0, p1) if p0["x"] <= p1["x"] else (p1, p0)
    assert left["x"] + left["w"] <= right["x"] + 1e-6, (
        f"panels must not overlap: left ends at {left['x'] + left['w']}, right starts at {right['x']}"
    )


def test_shared_legend_interactive_marks_stay_inside_plot_areas():
    """Every circle mark must sit inside its owning panel's plot_area.

    If the legend band offset were applied to the panel rect but not the mark
    coordinates (or the other way around), hit-testing — which gates on
    ``rect_contains(plot_area, click)`` — would silently miss every mark.
    """
    scene = _scene(_legend_pair(shared=True))
    for pi, panel in enumerate(scene["panels"]):
        pa = panel["plot_area"]
        for mb in panel["marks"]:
            for node in mb["nodes"]:
                if node["type"] != "circle":
                    continue
                r = node["r"]
                assert pa["x"] - r <= node["cx"] <= pa["x"] + pa["w"] + r, (
                    f"panel {pi}: circle cx={node['cx']} outside plot_area x-range "
                    f"[{pa['x']}, {pa['x'] + pa['w']}]"
                )
                assert pa["y"] - r <= node["cy"] <= pa["y"] + pa["h"] + r, (
                    f"panel {pi}: circle cy={node['cy']} outside plot_area y-range "
                    f"[{pa['y']}, {pa['y'] + pa['h']}]"
                )


# ============================================================================
# Export round-trip: the slot contract must survive into the HTML document
# ============================================================================


def test_dual_axis_to_html_embeds_slot_contract():
    """to_html() must embed the scene with y_domains/y_slot intact — the WASM
    loader in the exported document reads exactly this JSON."""
    html = _dual_layer().to_html(embed_wasm=False)
    assert "y_domains" in html, "exported HTML must embed the per-slot domain list"
    assert "y_slot" in html, "exported HTML must embed batch slot ids"


def test_dual_axis_scene_json_round_trips_through_json():
    """json load → dump → load must preserve the slot fields byte-for-value.

    Guards against non-JSON-safe values (NaN/Inf) sneaking into any slot field
    and against key loss in the coord/marks/tick_levels sections.
    """
    scene_json, _ = _render_scene(_dual_layer())
    scene = json.loads(scene_json, parse_constant=_reject_constant)
    rescene = json.loads(json.dumps(scene, allow_nan=False))
    assert rescene["panels"][0]["coord"]["y_domains"] == scene["panels"][0]["coord"]["y_domains"]
    assert [mb.get("y_slot", 0) for mb in rescene["panels"][0]["marks"]] == [0, 1]
    assert (
        rescene["interaction"]["tick_levels"][0]["y_slot_levels"]
        == scene["interaction"]["tick_levels"][0]["y_slot_levels"]
    )
